{"tool":"write","path":"tests/test_export.py","content":""""Optional tests for reports.export.export_csv."""
import unittest

from reports import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(
            export_csv([{"a": 1, "b": "x"}], ["a", "b"]),
            "a,b\r\n1,x\r\n",
        )

    def test_empty_columns_empty_rows(self):
        self.assertEqual(export_csv([], []), "\r\n")

    def test_empty_columns_with_rows(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n")

    def test_quoting(self):
        self.assertEqual(
            export_csv([{"v": 'he said "hi"'}], ["v"]),
            'v\r\n"he said ""hi"""\r\n',
        )

    def test_embedded_newlines(self):
        self.assertEqual(
            export_csv([{"v": "a\r\nb\nc"}], ["v"]),
            'v\r\n"a\r\nb\nc"\r\n',
        )

    def test_missing_and_none(self):
        self.assertEqual(
            export_csv([{"a": None}], ["a", "b"]),
            "a,b\r\n,\r\n",
        )

    def test_unselected_ignored(self):
        self.assertEqual(
            export_csv([{"a": 1, "c": 3}], ["a"]),
            "a\r\n1\r\n",
        )

    def test_non_str_values(self):
        self.assertEqual(
            export_csv([{"a": 1.5, "b": True}], ["a", "b"]),
            "a,b\r\n1.5,True\r\n",
        )

    def test_unicode(self):
        self.assertEqual(
            export_csv([{"a": "héllo"}], ["a"]),
            "a\r\nhéllo\r\n",
        )

    def test_generators(self):
        rows = ({"a": i} for i in range(3))
        cols = (c for c in ["a"])
        self.assertEqual(export_csv(rows, cols), "a\r\n0\r\n1\r\n2\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], [1])


if __name__ == "__main__":
    unittest.main()
